 function walkFacts(root){const stack=[root];while(stack.length){const value=stack.pop();if(value===null||typeof value!=='object'||objects.has(value))continue;objects.add(value);const kind=tag(value);
  if(['TypedOccurrence','LocalReferenceOccurrence','ScalarOccurrence','StringOccurrence','CaseOccurrence','LocalOccurrence'].includes(kind)){occurrences[kind]=(occurrences[kind]??0)+1;id(value.term,'node',kind+'.term');id(value.ty,'node',kind+'.ty');if(kind==='LocalReferenceOccurrence')id(value.value,'node',kind+'.value');}
  else if(kind==='CheckedBinding'||kind==='ArenaGlobal')id(value.ty,'node',kind+'.ty');else if(kind==='Symbol')id(value.signature,'node','Symbol.signature');else if(kind==='CheckedVariable'||kind==='CheckedConstructor')id(value.pattern,'pattern',kind+'.pattern');
  else if(kind==='Definition'){range(value.binders.start,value.binders.count,'binder','Definition.binders');optional(value.result,'Definition.result');}
  else if(kind==='TypeDecl'){range(value.params.start,value.params.count,'binder','TypeDecl.params');id(value.kind,'node','TypeDecl.kind');}
  else if(kind==='Constructor')range(value.fields.start,value.fields.count,'binder','Constructor.fields');else if(kind==='LawDecl')id(value.body,'node','LawDecl.body');else if(kind==='ClauseFor'){id(value.ty,'node','ClauseFor.ty');if(tag(value.condition)==='Some')id(value.condition.value,'node','ClauseFor.condition');}
  else if(kind==='DefTerm'||kind==='SomeTerm')id(value.term,'node',kind+'.term');else if(kind==='Names')range(value.start,value.count,'name','Names');
  for(const [key,child]of Object.entries(value))if(key!=='source'&&child!==null&&typeof child==='object')stack.push(child);
 }}
 walkFacts({modules:program.modules,signatures:program.signatures,metadata:program.metadata});
 while(pending.length){const [kind,value,label]=pending.pop();if(kind==='name'){const text=read('name_text',value);assert.ok(typeof text==='string'||tag(text)==='Con'||tag(text)==='Nil','Name representation '+label);continue;}const node=read(kind==='node'?'get_node':kind==='pattern'?'get_pattern':'get_binder',value),form=tag(node);kinds[kind+'.'+form]=(kinds[kind+'.'+form]??0)+1;
